<?php require_once '../config/db.php';require_once '../includes/auth.php';require_role('admin');$rows=$pdo->query("SELECT id,name,username,email,status FROM users WHERE role='student' ORDER BY name")->fetchAll();$page_title='Students';$css_path='../assets/css/style.css';$home_path='dashboard.php';$logout_path='../logout.php';$role='admin';include '../includes/header.php';?><div class="layout"><?php include '../includes/sidebar.php';?><h1 class="page-title">Students</h1><div class="table-card"><table><thead><tr><th>Name</th><th>Username</th><th>Email</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['username'])?></td><td><?=e($r['email'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></main></div><?php include '../includes/footer.php';?>